    if (inShadow) { fn(); return; }
    const dpr = devicePixelRatio || 1, main = ctx, s = DROP.scale;
    const sx = x + DROP.dx + DROP.spread * (x / W - 0.5) * 2, sy = y + DROP.dy + DROP.spread * (y / H - 0.5) * 2;
    shadowG.setTransform(dpr * s, 0, 0, dpr * s, dpr * (sx - x * s), dpr * (sy - y * s)); // (x, y) lands on (sx, sy), shrunk
