    const l = Math.floor(Math.min(c.x, t.x) - pad), tp = Math.floor(Math.min(c.y, t.y) - pad);
    const w = Math.ceil(Math.max(c.x, t.x) + pad) - l, h = Math.ceil(Math.max(c.y, t.y) + pad) - tp;
