      g.font = c.tag.font;
      const w = g.measureText(text).width, size = parseFloat(/(\d+(?:\.\d+)?)px/.exec(c.tag.font)?.[1]) || 15;
      const cw = Math.ceil(w + 2 * HB_PAD), ch = Math.ceil(size * 1.6 + 2 * HB_PAD);
      cv.width = Math.ceil(cw * dpr); cv.height = Math.ceil(ch * dpr);
