    again.addEventListener('click', (e) => { e.stopPropagation(); playAgainFromEnd(); });
    box.append(h, again);
    const col = layoutBox(document.querySelector('[data-testid=primaryColumn]'));
    const w = col?.width || innerWidth;
    box.style.left = `${Math.round(col?.width ? col.left + col.width / 2 : innerWidth / 2)}px`;
    h.style.fontSize = `${Math.round(Math.max(24, Math.min(46, (w - 80) / 12.5)))}px`; // (fits the column, card and all)
    document.documentElement.append(box);
